dict.string:
export PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:$PATH"

projects_output="$(jean projects list 2>&1)"
cli_status=$?

JEAN_PROJECTS_OUTPUT="$projects_output" JEAN_PROJECTS_STATUS="$cli_status" python3 - <<'PY'
import json
import os
import re

output = os.environ.get("JEAN_PROJECTS_OUTPUT", "")
status = os.environ.get("JEAN_PROJECTS_STATUS", "1")

def item(title, subtitle, valid=False):
    return {
        "items": [{
            "title": title,
            "subtitle": subtitle,
            "valid": valid,
            "icon": {"path": "icon.png"},
        }]
    }

if status != "0":
    print(json.dumps(item("Jean CLI project list failed", output.strip() or "Run `jean projects list` in Terminal for details.")))
    raise SystemExit

lines = [line.rstrip() for line in output.splitlines() if line.strip()]
if not lines or lines[0].startswith("No Jean projects found"):
    print(json.dumps(item("No Jean projects found", "Add a project in Jean before using `yp`.")))
    raise SystemExit

projects = []
for line in lines[1:]:
    parts = re.split(r"\s{2,}", line, maxsplit=3)
    if len(parts) != 4:
        continue
    project_id, name, branch, path = parts
    projects.append({
        "title": name,
        "subtitle": f"{branch} - {path}",
        "arg": project_id,
        "match": f"{name} {branch} {path} {project_id}",
        "valid": True,
        "icon": {"path": "icon.png"},
        "variables": {
            "project_name": name,
            "project_path": path,
        },
    })

if projects:
    print(json.dumps({"items": projects}))
else:
    print(json.dumps(item("No Jean projects parsed", "Run `jean projects list` in Terminal to inspect the output.")))
PY
